(() => {
  const root=document.getElementById('iwr-geek-waves');
  const canvas=root.querySelector('canvas');
  const ctx=canvas.getContext('2d');
  const record=root.querySelector('.gx-record');
  const clock=root.querySelector('[data-clock]');
  const description=root.querySelector('[data-description]');
  const pause=root.querySelector('[data-pause]');
  const reduced=matchMedia('(prefers-reduced-motion: reduce)');
  const state={style:'wireframe',mode:'play',paused:false,tone:'white',gain:0.8};
  const captions={
    teletext:'Basamaklı, dikdörtgen mozaikler; ses yükseldikçe merkezden açılan teletext dalgası.',
    scope:'İnce vektör izi ve sönümlenen katmanlar; laboratuvar osiloskobu gibi kıvrılan bir sinyal.',
    wireframe:'Silk’in katman hissi, tel kafes bir araziye dönüşüyor; sesle kabarıp geriye akıyor.',
    ascii:'Nokta, iki nokta, yıldız ve # karakterleri; sesin yoğunluğunu yazıya çeviren terminal dokusu.',
    spectral:'Frekans izi hissi veren piksel sütunları; sağdan yazılıp sola akan bir sinyal şeridi.'
  };
  const names={teletext:'Teletext Pulse',scope:'Vector Scope',wireframe:'Wireframe Echo',ascii:'ASCII Stream',spectral:'Spectral Tape'};
  const colors={white:'#f1f1ee',green:'#a0f0b0',amber:'#FF0000'};
  let w=226,h=44,t=3.2,last=0,level=0.5,recordTime=0;
  // Live sound seam: iwrSignal exists only inside the archive gallery. Without it, or with sound off, nothing changes.
  const live=()=>typeof iwrSignal!=='undefined'&&iwrSignal.active?iwrSignal:null;
  const heard=(s,time)=>{const age=Math.max(0,t-time);return 0.13+0.87*Math.max(s.levelAt(age),s.hitAt(age));};
  function clamp(v,lo=0,hi=1){return Math.min(hi,Math.max(lo,v));}
  function amp(time){const s=live();if(s)return heard(s,time);return 0.15+0.52*Math.pow(Math.sin(time*1.65),4)+0.26*Math.pow(Math.sin(time*3.15+0.7),8);}
  function audio(time){return Math.sin(time*15)*0.55+Math.sin(time*24.3+0.8)*0.28+Math.sin(time*37.7)*0.17;}
  function tint(alpha=1){ctx.fillStyle=colors[state.tone];ctx.strokeStyle=colors[state.tone];ctx.globalAlpha=alpha;}
  function line(points,alpha=1,width=1){
    ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));
    tint(alpha);ctx.lineWidth=width;ctx.lineCap='butt';ctx.stroke();ctx.globalAlpha=1;
  }
  function teletext(time,gain){
    const cols=Math.max(8,Math.floor(w/7)),rows=8,pitch=w/cols;
    const tick=Math.floor(time*9)/9;
    for(let c=0;c<cols;c++){
      const x=c/(cols-1);
      const local=state.mode==='record'?amp(tick-(1-x)*2.5):gain*(0.4+0.6*Math.abs(audio(tick+x*0.6)));
      const extent=Math.max(1,Math.round(local*4));
      for(let r=0;r<rows;r++){
        const d=Math.abs(r-3.5),lit=d<extent;
        if(!lit)continue;
        tint(d>extent-1?0.9:0.43+0.22*local);
        ctx.fillRect(Math.floor(c*pitch)+1,3+r*4.75,Math.max(2,Math.floor(pitch)-1.5),4);
      }
    }
    ctx.globalAlpha=1;
  }
  function scope(time,gain){
    const cy=22,cx=w/2;
    line([[1,cy],[w-1,cy]],0.13,0.7);
    line([[cx,2],[cx,42]],0.13,0.7);
    for(let x=10;x<w;x+=12)line([[x,cy-1.5],[x,cy+1.5]],0.2,0.7);
    for(let trail=5;trail>=0;trail--){
      const age=trail*0.045,phase=time-age;
      const sx=(w/2-5)*(0.55+gain*0.4),sy=5+gain*14;
      const points=[];
      for(let i=0;i<=220;i++){
        const a=i/220*Math.PI*2;
        const x=cx+sx*Math.sin(a*2+Math.sin(phase*0.6)*0.48);
        const y=cy+sy*Math.sin(a*3+phase*(state.mode==='record'?0.6:0.38));
        points.push([x,y]);
      }
      line(points,trail===0?0.95:0.08+(5-trail)*0.015,trail===0?1:0.65);
    }
  }
  function terrainPoint(u,v,time,gain){
    const perspective=0.60+v*0.40;
    const x=w/2+(u-0.5)*(w-4)*perspective;
    const swell=0.6+0.4*Math.sin(time*1.8-v*4.5);
    const shape=Math.pow(Math.sin(Math.PI*u),1.1)*(0.45*Math.sin(u*14+v*3.4-time*1.6)+0.55*Math.sin(u*8-time*1.1-v*1.7));
    const baseline=7+30*v;
    const height=Math.min(3+gain*9,baseline-2,42-baseline);
    return [x,baseline+shape*height*swell];
  }
  function wireframe(time,gain){
    for(let r=0;r<9;r++){
      const v=r/8,points=[];
      for(let c=0;c<=58;c++)points.push(terrainPoint(c/58,v,time,gain));
      line(points,0.16+v*0.64,0.75);
    }
    for(let c=0;c<23;c++){
      const points=[];
      for(let r=0;r<=32;r++)points.push(terrainPoint(c/22,r/32,time,gain));
      line(points,0.30,0.5);
    }
  }
  function ascii(time,gain){
    const chars=['.',':','+','*','#','@'];
    const cols=Math.max(4,Math.floor(w/7)),pitch=w/cols;
    const tick=Math.floor(time*7)/7;
    ctx.font='11px ui-monospace, SFMono-Regular, Menlo, monospace';ctx.textAlign='center';ctx.textBaseline='middle';
    for(let r=0;r<3;r++)for(let c=0;c<cols;c++){
      const x=c/(cols-1),sample=amp(tick-(1-x)*(state.mode==='record'?3:1.6))*state.gain/0.8;
      const mod=0.62+0.38*Math.sin(c*0.6+tick*4-r*2);
      const density=clamp(sample*mod+(r===1?0.19:-0.05));
      const index=Math.min(chars.length-1,Math.floor(density*chars.length));
      tint(0.19+0.80*density);
      ctx.fillText(chars[index],c*pitch+pitch/2,9+r*13);
    }
    ctx.globalAlpha=1;
  }
  function spectrumAt(time,freq){
    const s=live();if(s?.spectrumAt)return s.spectrumAt(freq,Math.max(0,t-time));
    const f1=0.24+0.1*Math.sin(time*0.7),f2=0.6+0.18*Math.sin(time*1.3);
    const a=Math.exp(-Math.pow((freq-f1)/0.14,2));
    const b=Math.exp(-Math.pow((freq-f2)/0.095,2));
    const noise=0.5+0.5*Math.sin(time*9+freq*22)*Math.cos(time*4-freq*34);
    return clamp((a+b*0.78)*amp(time)*1.22+noise*0.08);
  }
  function spectral(time,gain){
    const rows=11,cols=Math.max(10,Math.floor(w/3));
    const tick=Math.floor(time*10)/10;
    const speed=state.mode==='record'?0.12:0.075;
    const pitch=w/cols;
    for(let c=0;c<cols;c++)for(let r=0;r<rows;r++){
      const sample=spectrumAt(tick-(cols-1-c)*speed,1-r/(rows-1))*state.gain/0.8;
      if(sample<0.10)continue;
      tint(Math.round(clamp(sample)*5)/5*0.88+0.08);
      ctx.fillRect(Math.floor(c*pitch),r*4,Math.max(1,Math.floor(pitch)-0.75),3);
    }
    line([[w-0.5,1],[w-0.5,43]],0.64,1);
    ctx.globalAlpha=1;
  }
  function draw(){
    ctx.clearRect(0,0,w,h);
    const time=reduced.matches?3.2:t;
    const gain=reduced.matches?0.4+level*0.15:level;
    ({teletext,scope,wireframe,ascii,spectral})[state.style](time,gain);
  }
  function resize(){
    w=Math.max(1,canvas.getBoundingClientRect().width);
    const dpr=Math.min(devicePixelRatio||1,3);
    canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);
    ctx.setTransform(dpr,0,0,dpr,0,0);draw();
  }
  function sync(){
    root.querySelectorAll('[data-style]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.style===state.style)));
    root.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===state.mode)));
    record.hidden=state.mode!=='record';
    pause.textContent=state.paused?'Devam et':'Duraklat';pause.setAttribute('aria-pressed',String(state.paused));
    description.textContent=captions[state.style];
    canvas.setAttribute('aria-label',names[state.style]+': '+captions[state.style]);
    resize();
  }
  root.querySelectorAll('[data-style]').forEach(b=>b.addEventListener('click',()=>{state.style=b.dataset.style;sync();}));
  root.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{state.mode=b.dataset.mode;recordTime=0;sync();}));
  pause.addEventListener('click',()=>{state.paused=!state.paused;sync();});
  function frame(now){
    if(!root.isConnected)return;
    const dt=last?Math.min((now-last)/1000,0.05):0;last=now;
    if(!state.paused&&!document.hidden){
      t+=dt;recordTime+=dt;
      const target=clamp(amp(t)*state.gain/0.8);
      level+=(target-level)*(1-Math.exp(-dt/(target>level?0.08:0.24)));
      draw();
      const n=Math.floor(recordTime*100)%6000;
      clock.textContent=String(Math.floor(n/100)).padStart(2,'0')+':'+String(n%100).padStart(2,'0');
    }
    requestAnimationFrame(frame);
  }
  const observer=new ResizeObserver(resize);observer.observe(canvas);
  sync();requestAnimationFrame(frame);
  if(globalThis.Tweak){
    const tweaks=new Tweak({container:root.querySelector('.gx-phone'),onChange:sync});
    tweaks.addSelect(state,'tone',{label:'Fosfor rengi',options:[{label:'Beyaz',value:'white'},{label:'Yeşil',value:'green'},{label:'Amber',value:'amber'}]});
    tweaks.addSlider(state,'gain',{label:'Sinyal yoğunluğu',min:0.2,max:1,step:0.05});
  }
})();
